import { queryOptions, useQuery } from '@tanstack/vue-query'
import { computed, toValue } from 'vue'
import type { MaybeRefOrGetter } from 'vue'

export interface CatalogItem {
  id: number
  name: string
  price: number
}

export interface CatalogFilters {
  categoryId?: number
  search?: string
}

function normalizeFilters(filters: CatalogFilters): CatalogFilters {
  const normalized: CatalogFilters = {}
  if (filters.categoryId !== undefined) {
    normalized.categoryId = filters.categoryId
  }
  if (filters.search) {
    normalized.search = filters.search
  }
  return normalized
}

async function fetchCatalog(filters: CatalogFilters): Promise<CatalogItem[]> {
  const params = new URLSearchParams()
  if (filters.categoryId !== undefined) {
    params.set('categoryId', String(filters.categoryId))
  }
  if (filters.search) {
    params.set('search', filters.search)
  }
  const response = await fetch(`/api/catalog?${params.toString()}`)
  if (!response.ok) {
    throw new Error(`Failed to load catalog: ${response.status}`)
  }
  return (await response.json()) as CatalogItem[]
}

export function catalogQueryOptions(filters: MaybeRefOrGetter<CatalogFilters> = {}) {
  const keyFilters = computed(() => normalizeFilters(toValue(filters)))
  return queryOptions({
    queryKey: ['catalog', keyFilters],
    queryFn: () => fetchCatalog(normalizeFilters(toValue(filters))),
    staleTime: 60_000,
  })
}

export function useCatalogQuery(filters: MaybeRefOrGetter<CatalogFilters> = {}) {
  return useQuery(catalogQueryOptions(filters))
}

